    def _determine_route(self, model_uri: str) -> str:
        # A bare string with no provider prefix (e.g. "databricks", "gpt-oss-120b")
        # routes to the Databricks managed judge endpoint.
        if ":/" not in model_uri:
            self._provider = None
            self._raw_model_name = model_uri
            self._model_name = model_uri
            return "databricks"

        provider, raw_model_name = _parse_model_uri(model_uri)
        self._provider = provider
        self._raw_model_name = raw_model_name
        self._model_name = f"{provider}/{raw_model_name}"

        if provider == "endpoints":
            return "endpoints"

        # Use the native gateway provider infrastructure when it can construct a
        # provider instance (supported provider with the required credentials);
        # otherwise fall back to litellm.
        try:
            _get_provider_instance(provider, raw_model_name)
        except MlflowException:
